import com.example.lending.domain.Book;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/books")
public class BookController {

    private final RegisterBookUseCase registerBookUseCase;
    private final GetBookUseCase getBookUseCase;
    private final SearchBookUseCase searchBookUseCase;

    public BookController(RegisterBookUseCase registerBookUseCase, GetBookUseCase getBookUseCase,
                          SearchBookUseCase searchBookUseCase) {
        this.registerBookUseCase = registerBookUseCase;
        this.getBookUseCase = getBookUseCase;
        this.searchBookUseCase = searchBookUseCase;
    }

    @GetMapping
    public List<BookResponse> searchBooks(@RequestParam String title) {
        return searchBookUseCase.searchByTitle(new SearchByTitleQuery(title)).stream()
                .map(BookResponse::from)
                .toList();
    }

    @GetMapping("/{id}")
    public BookResponse getBook(@PathVariable UUID id) {
        return BookResponse.from(getBookUseCase.getBook(id));
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public BookResponse registerBook(@RequestBody RegisterBookRequest request) {
        Book book = registerBookUseCase.registerBook(new RegisterBookCommand(request.title()));
        return BookResponse.from(book);
    }
}
